package dev.watchtv.tv;

import android.app.Activity;
import android.content.Intent;
import android.content.ActivityNotFoundException;
import android.graphics.Color;
import android.net.Uri;
import android.os.Bundle;
import android.view.Gravity;
import android.view.KeyEvent;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
 private static final int PICK=40, BG=Color.rgb(17,21,18), FG=Color.rgb(232,235,229), ACCENT=Color.rgb(199,237,156);
 private final ExecutorService workers=Executors.newSingleThreadExecutor();
 private LinearLayout root,content; private EditText query; private String currentQuery=""; private volatile long requestId=0; private VideoView player;
 private JSONArray sources=new JSONArray(); private String screen="home"; private JSONObject currentVideo; private String currentSource="";
 private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{sources=new JSONArray(getPreferences(0).getString("sources","[]"));}catch(Exception ignored){} showHome();}
 @Override protected void onDestroy(){requestId++;workers.shutdownNow();super.onDestroy();}
 private TextView label(String text,int size){TextView t=new TextView(this);t.setText(text);t.setTextColor(FG);t.setTextSize(size);t.setPadding(dp(8),dp(8),dp(8),dp(8));return t;}
 private Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(16);b.setTextColor(FG);b.setAllCaps(false);b.setBackgroundColor(Color.rgb(42,53,39));b.setFocusable(true);b.setOnFocusChangeListener((v,focused)->{b.setBackgroundColor(focused?ACCENT:Color.rgb(42,53,39));b.setTextColor(focused?BG:FG);});b.setOnClickListener(v->action.run());return b;}
 private void addButton(LinearLayout row,String text,Runnable action){Button b=button(text,action);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(b,p);}
 private void frame(String title){player=null;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(26),dp(14),dp(26),dp(14));root.addView(label("WatchTV  ·  "+title,24));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private int enabledCount(){int count=0;for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);if(s!=null&&s.optBoolean("enabled",true))count++;}return count;}
 private void showHome(){screen="home";frame("电视版");content.addView(label("来源和播放均在电视本机运行",16));LinearLayout controls=new LinearLayout(this);controls.setOrientation(LinearLayout.HORIZONTAL);query=new EditText(this);query.setSingleLine(true);query.setText(currentQuery);query.setHint("输入影片名称");query.setTextColor(FG);query.setHintTextColor(Color.LTGRAY);query.setTextSize(18);controls.addView(query,new LinearLayout.LayoutParams(0,dp(56),1));addButton(controls,"搜索",()->startSearch(query.getText().toString()));content.addView(controls);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);addButton(actions,"导入来源 JSON",this::pickSources);addButton(actions,"来源管理（"+enabledCount()+" 个启用）",this::showSources);content.addView(actions);content.addView(label("请先从 U 盘或电视文件管理器导入 WatchTV 来源 JSON。搜索结果取决于来源和网络。",16));}
 private void pickSources(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,PICK);}catch(ActivityNotFoundException e){toast("电视没有文件选择器，请先安装支持文件选择的文件管理器");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK||result!=RESULT_OK||data==null)return;try(InputStream in=getContentResolver().openInputStream(data.getData())){String text=read(in,1024*1024);Object parsed=new JSONTokener(text).nextValue();JSONArray list=parsed instanceof JSONArray?(JSONArray)parsed:((JSONObject)parsed).optJSONArray("sources");if(list==null||list.length()>50)throw new Exception("请导入包含 sources 的 JSON（最多 50 个）");JSONArray valid=new JSONArray();HashSet<String> seen=new HashSet<>();for(int i=0;i<list.length();i++){JSONObject s=list.optJSONObject(i);if(s==null)throw new Exception("来源格式不正确");String url=s.optString("url","").trim();if(!UrlPolicy.accept(url))throw new Exception("来源地址无效或使用了内网地址");if(!seen.add(url))continue;JSONObject v=new JSONObject();v.put("url",url);v.put("name",s.optString("name",Uri.parse(url).getHost()));v.put("enabled",s.optBoolean("enabled",true));valid.put(v);}sources=valid;saveSources();toast("已导入 "+sources.length()+" 个来源");showHome();}catch(Exception e){toast("导入失败："+e.getMessage());}}
 private void saveSources(){getPreferences(0).edit().putString("sources",sources.toString()).apply();}
 private void showSources(){screen="sources";frame("来源管理");LinearLayout actions=new LinearLayout(this);addButton(actions,"返回",this::showHome);addButton(actions,"导入 JSON",this::pickSources);content.addView(actions);if(sources.length()==0)content.addView(label("尚未导入来源",18));for(int i=0;i<sources.length();i++){final int index=i;JSONObject s=sources.optJSONObject(i);if(s==null)continue;boolean on=s.optBoolean("enabled",true);Button b=button((on?"● 已启用  ":"○ 已停用  ")+s.optString("name"),()->{try{s.put("enabled",!on);saveSources();showSources();}catch(Exception ignored){}});content.addView(b);}}
 private static String read(InputStream in,int limit)throws IOException{if(in==null)throw new IOException("无法读取文件");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>limit)throw new IOException("文件或响应过大");out.write(b,0,n);}return out.toString("UTF-8");}
 private static boolean publicHost(String host)throws IOException{for(InetAddress a:InetAddress.getAllByName(host)){byte[] b=a.getAddress();if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress())return false;if(b.length==4){int x=b[0]&255,y=b[1]&255;if((x==100&&y>=64&&y<=127)||(x==198&&(y==18||y==19))||x>=224)return false;}else if((b[0]&0xfe)==0xfc)return false;}return true;}
 private static JSONObject fetch(String url)throws Exception{if(!UrlPolicy.accept(url))throw new IOException("来源地址不受支持");URL u=new URL(url);if(!publicHost(u.getHost()))throw new IOException("来源解析到内网或保留地址");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","Mozilla/5.0 WatchTV");try{if(c.getResponseCode()!=200)throw new IOException("来源返回 HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream()){return new JSONObject(read(in,4*1024*1024));}}finally{c.disconnect();}}
 private void startSearch(String value){String term=value.trim();if(term.isEmpty()){toast("请输入片名");return;}if(enabledCount()==0){toast("请先导入并启用来源");return;}currentQuery=term;long id=++requestId;screen="search";frame("搜索："+term);LinearLayout bar=new LinearLayout(this);addButton(bar,"返回",()->{requestId++;showHome();});content.addView(bar);TextView status=label("正在搜索来源…",16);content.addView(status);JSONArray copy;try{copy=new JSONArray(sources.toString());}catch(Exception e){return;}workers.execute(()->{int done=0,errors=0,found=0;for(int i=0;i<copy.length()&&found<200&&!Thread.currentThread().isInterrupted();i++){if(id!=requestId)return;JSONObject s=copy.optJSONObject(i);if(s==null||!s.optBoolean("enabled",true))continue;String src=s.optString("url"),name=s.optString("name");try{Uri.Builder u=Uri.parse(src).buildUpon().appendQueryParameter("ac","videolist").appendQueryParameter("wd",term).appendQueryParameter("pg","1");JSONArray list=fetch(u.build().toString()).optJSONArray("list");if(list==null)throw new IOException("无有效列表");for(int j=0;j<Math.min(100,list.length())&&found<200;j++){JSONObject item=list.optJSONObject(j);if(item==null||item.optString("vod_name").isEmpty())continue;found++;runOnUiThread(()->{if(id!=requestId||!"search".equals(screen))return;Button b=button(item.optString("vod_name")+"  ·  "+name+"  "+item.optString("vod_remarks"),()->openVideo(item,name,src));content.addView(b);});}}catch(Exception e){errors++;}done++;final int d=done,f=found,err=errors;runOnUiThread(()->{if(id==requestId&&"search".equals(screen))status.setText("已完成 "+d+" 个来源，找到 "+f+" 条结果"+(f>=200?"（已达显示上限）":"")+(err>0?"，"+err+" 个来源不可用":""));});}});}
 private void openVideo(JSONObject item,String source,String sourceUrl){
  if(!item.optString("vod_play_url").isEmpty()){showVideo(item,source);return;}
  String vodId=item.optString("vod_id");if(vodId.isEmpty()){showVideo(item,source);return;}
  long id=++requestId;screen="loading";frame(item.optString("vod_name"));content.addView(label("正在加载剧集…",18));addButton(content,"返回搜索",()->startSearch(currentQuery));
  workers.execute(()->{try{String u=Uri.parse(sourceUrl).buildUpon().appendQueryParameter("ac","videolist").appendQueryParameter("ids",vodId).build().toString();JSONArray list=fetch(u).optJSONArray("list");JSONObject detail=list!=null?list.optJSONObject(0):null;runOnUiThread(()->{if(id==requestId&&"loading".equals(screen)){if(detail==null){toast("来源没有返回剧集");showVideo(item,source);}else showVideo(detail,source);}});}catch(Exception e){runOnUiThread(()->{if(id==requestId&&"loading".equals(screen)){toast("加载剧集失败，请重试或切换来源");showVideo(item,source);}});}});
 }
 private void showVideo(JSONObject item,String source){screen="detail";currentVideo=item;currentSource=source;frame(item.optString("vod_name"));LinearLayout nav=new LinearLayout(this);addButton(nav,"返回搜索",()->startSearch(currentQuery));addButton(nav,"返回首页",this::showHome);content.addView(nav);content.addView(label("来源："+source+"   "+item.optString("vod_remarks"),16));String[] names=item.optString("vod_play_from").split("\\$\\$\\$",-1);String[] lines=item.optString("vod_play_url").split("\\$\\$\\$",-1);int added=0;for(int i=0;i<lines.length;i++){String[] eps=lines[i].split("#");boolean heading=false;for(int j=0;j<eps.length;j++){String e=eps[j];int split=e.indexOf('$');String title=split>=0?e.substring(0,split):"第 "+(j+1)+" 集";String url=split>=0?e.substring(split+1):e;if(!UrlPolicy.accept(url)||!url.matches("(?i).*\\.(m3u8|mp4|m4v)(\\?.*)?$"))continue;if(!heading){content.addView(label(i<names.length&&!names[i].isEmpty()?names[i]:"线路 "+(i+1),19));heading=true;}final String playable=url;content.addView(button(title,()->play(playable)));added++;}}if(added==0)content.addView(label("没有可直接播放的 HLS 或 MP4 线路，请尝试其他来源。",17));}
 private void play(String url){screen="player";root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);root.addView(label(currentVideo.optString("vod_name")+"  ·  "+currentSource,18));player=new VideoView(this);root.addView(player,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);addButton(controls,"播放 / 暂停",()->{if(player.isPlaying())player.pause();else player.start();});addButton(controls,"后退 10 秒",()->player.seekTo(Math.max(0,player.getCurrentPosition()-10000)));addButton(controls,"前进 10 秒",()->player.seekTo(player.getCurrentPosition()+10000));addButton(controls,"返回剧集",()->{player.stopPlayback();showVideo(currentVideo,currentSource);});root.addView(controls);setContentView(root);player.setOnErrorListener((mp,what,extra)->{toast("播放失败，请检查网络或切换来源、线路");return true;});long id=++requestId;workers.execute(()->{try{if(!publicHost(new URL(url).getHost()))throw new IOException("播放地址解析到内网或保留地址");runOnUiThread(()->{if(id==requestId&&"player".equals(screen)&&player!=null){player.setVideoURI(Uri.parse(url));player.start();}});}catch(Exception e){runOnUiThread(()->{if(id==requestId&&"player".equals(screen))toast("播放地址无法访问，请切换来源或线路");});}});controls.getChildAt(0).requestFocus();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override public void onBackPressed(){requestId++;if("player".equals(screen)){if(player!=null)player.stopPlayback();showVideo(currentVideo,currentSource);}else if("detail".equals(screen))startSearch(currentQuery);else if(!"home".equals(screen))showHome();else super.onBackPressed();}
}
